NAME=infisical
BINARY=packer-plugin-${NAME}
PLUGIN_FQN="$(shell grep -E '^module' <go.mod | sed -E 's/module *//')"

COUNT?=1
TEST?=$(shell go list ./...)
HASHICORP_PACKER_PLUGIN_SDK_VERSION?=$(shell go list -m github.com/hashicorp/packer-plugin-sdk | cut -d " " -f2)

.PHONY: dev

build:
	@go build -o ${BINARY}

dev:
	@go build -ldflags="-X '${PLUGIN_FQN}/version.VersionPrerelease=dev'" -o '${BINARY}'
	packer plugins install --path ${BINARY} "$(shell echo "${PLUGIN_FQN}" | sed 's/packer-plugin-//')"

test:
	@go test -race -count $(COUNT) $(TEST) -timeout=3m

install-packer-sdc: ## Install packer sofware development command
	@go install github.com/hashicorp/packer-plugin-sdk/cmd/packer-sdc@${HASHICORP_PACKER_PLUGIN_SDK_VERSION}

plugin-check: install-packer-sdc build
	@packer-sdc plugin-check ${BINARY}

testacc: dev
	@PACKER_ACC=1 go test -count $(COUNT) -v $(TEST) -timeout=120m

generate: install-packer-sdc
	@go generate ./...
	@rm -rf .docs
	@packer-sdc renderdocs -src "docs" -partials docs-partials/ -dst ".docs/"
	@./.web-docs/scripts/compile-to-webdocs.sh "." ".docs" ".web-docs" "infisical"
	@rm -r ".docs"

package main

import (
	"fmt"
	"os"

	"github.com/hashicorp/packer-plugin-sdk/plugin"
	"github.com/infisical/packer-plugin-infisical/datasource/secrets"
	"github.com/infisical/packer-plugin-infisical/version"
)

func main() {
	pps := plugin.NewSet()
	pps.RegisterDatasource("secrets", new(secrets.Datasource))
	pps.SetVersion(version.PluginVersion)
	err := pps.Run()
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
}

package infisicalclient

import (
	"encoding/json"
	"fmt"
	"strconv"
)

func (client Client) GetSecretsRawV3(request GetRawSecretsV3Request) (GetRawSecretsV3Response, error) {
	var secretsResponse GetRawSecretsV3Response

	httpRequest := client.Config.HttpClient.
		R().
		SetResult(&secretsResponse).
		SetHeader("User-Agent", USER_AGENT).
		SetQueryParams(map[string]string{
			"environment":            request.Environment,
			"workspaceId":            request.WorkspaceId,
			"expandSecretReferences": strconv.FormatBool(request.ExpandSecretReferences),
		})

	if request.SecretPath != "" {
		httpRequest.SetQueryParam("secretPath", request.SecretPath)
	}

	response, err := httpRequest.Get("api/v3/secrets/raw")

	if err != nil {
		return GetRawSecretsV3Response{}, fmt.Errorf("CallGetSecretsRawV3: Unable to complete api request [err=%s]", err)
	}

	if response.IsError() {
		// Attempt to extract the specific error message from the JSON response body
		var apiErrorDetail struct {
			Message string `json:"message"`
		}

		if unmarshalErr := json.Unmarshal(response.Body(), &apiErrorDetail); unmarshalErr == nil && apiErrorDetail.Message != "" {
			return GetRawSecretsV3Response{}, fmt.Errorf("CallGetSecretsRawV3: API error: %s", apiErrorDetail.Message)
		}

		// Fallback if JSON parsing fails or the "message" field is not found or is empty.
		return GetRawSecretsV3Response{}, fmt.Errorf("CallGetSecretsRawV3: Unsuccessful response (Status: %s). Please make sure your secret path, workspace and environment name are all correct. Raw body: %s", response.Status(), response.String())
	}

	return secretsResponse, nil
}

func (client Client) GetRawSecrets(secretFolderPath string, envSlug string, workspaceId string) ([]RawV3Secret, error) {
	request := GetRawSecretsV3Request{
		Environment:            envSlug,
		WorkspaceId:            workspaceId,
		ExpandSecretReferences: true,
	}

	if secretFolderPath != "" {
		request.SecretPath = secretFolderPath
	}

	secrets, err := client.GetSecretsRawV3(request)

	if err != nil {
		return nil, err
	}

	return secrets.Secrets, nil
}

package infisicalclient

import (
	"fmt"

	"github.com/go-resty/resty/v2"
)

type Client struct {
	Config Config
}

type AuthStrategyType string

var AuthStrategy = struct {
	SERVICE_TOKEN               AuthStrategyType
	UNIVERSAL_MACHINE_IDENTITY  AuthStrategyType
	OIDC_MACHINE_IDENTITY       AuthStrategyType
	TOKEN_MACHINE_IDENTITY      AuthStrategyType
	KUBERNETES_MACHINE_IDENTITY AuthStrategyType
}{
	SERVICE_TOKEN:               "[REDACTED]",
	UNIVERSAL_MACHINE_IDENTITY:  "UNIVERSAL_MACHINE_IDENTITY",
	OIDC_MACHINE_IDENTITY:       "OIDC_MACHINE_IDENTITY",
	TOKEN_MACHINE_IDENTITY:      "TOKEN_MACHINE_IDENTITY",
	KUBERNETES_MACHINE_IDENTITY: "KUBERNETES_MACHINE_IDENTITY",
}

type Config struct {
	HostURL string

	AuthStrategy          AuthStrategyType
	IsMachineIdentityAuth bool

	// Service Token Auth
	ServiceToken string

	// Universal Machine Identity Auth
	ClientId     string
	ClientSecret string

	// Token machine identity auth
	Token string

	//OIDC Machine Identity Auth
	IdentityId       string
	OidcTokenEnvName string

	// Kubernetes Machine Identity Auth
	ServiceAccountToken     string
	ServiceAccountTokenPath string

	EnvSlug     string
	SecretsPath string
	HttpClient  *resty.Client // By default a client will be created
}

func NewClient(cnf Config) (*Client, error) {
	if cnf.HttpClient == nil {
		cnf.HttpClient = resty.New()
		cnf.HttpClient.SetBaseURL(cnf.HostURL)
	}

	var usingServiceToken = [REDACTED] != ""

	selectedAuthStrategy := cnf.AuthStrategy
	if cnf.ClientId != "" && cnf.ClientSecret != "" && selectedAuthStrategy == "" {
		selectedAuthStrategy = AuthStrategy.UNIVERSAL_MACHINE_IDENTITY
	}

	// Check if the user got multiple configured authentication methods, or none set at all.
	if usingServiceToken && selectedAuthStrategy != "" {
		return nil, fmt.Errorf("you have configured multiple authentication methods, please only use one")
	} else if !usingServiceToken && selectedAuthStrategy == "" {
		return nil, fmt.Errorf("you must configure an authentication method such as service tokens or Universal Auth before making calls")
	}

	if usingServiceToken {
		cnf.HttpClient.SetAuthToken(cnf.ServiceToken)
		cnf.AuthStrategy = AuthStrategy.SERVICE_TOKEN
	} else {
		authStrategies := map[AuthStrategyType]func() (string, error){
			AuthStrategy.UNIVERSAL_MACHINE_IDENTITY:  Client{cnf}.UniversalMachineIdentityAuth,
			AuthStrategy.OIDC_MACHINE_IDENTITY:       Client{cnf}.OidcMachineIdentityAuth,
			AuthStrategy.TOKEN_MACHINE_IDENTITY:      Client{cnf}.TokenMachineIdentityAuth,
			AuthStrategy.KUBERNETES_MACHINE_IDENTITY: Client{cnf}.KubernetesMachineIdentityAuth,
		}

		token, err := authStrategies[selectedAuthStrategy]()
		if err != nil {
			return nil, fmt.Errorf("unable to authenticate with machine identity [err=%s]", err)
		}

		cnf.AuthStrategy = selectedAuthStrategy
		cnf.IsMachineIdentityAuth = true
		cnf.HttpClient.SetAuthToken(token)
	}

	// These two if statements were a part of an older migration.
	// And when people upgraded to the newer version, we needed a way to indicate that the EnvSlug and SecretsPath are no longer defined on a provider-level.
	if cnf.EnvSlug != "" {
		return nil, fmt.Errorf("you must set the environment before making calls")
	}

	if cnf.SecretsPath != "" {
		return nil, fmt.Errorf("you must specify the secrets path before making calls")
	}

	cnf.HttpClient.SetHeader("Accept", "application/json")

	return &Client{cnf}, nil
}

package infisicalclient

import (
	"fmt"
	"os"
)

func (client Client) UniversalMachineIdentityAuth() (string, error) {
	if client.Config.ClientId == "" || client.Config.ClientSecret == "" {
		return "", fmt.Errorf("you must set the client secret and client ID for the client before making calls")
	}

	var loginResponse MachineIdentityAuthResponse

	res, err := client.Config.HttpClient.R().SetResult(&loginResponse).SetHeader("User-Agent", USER_AGENT).SetBody(map[string]string{
		"clientId":     client.Config.ClientId,
		"clientSecret": [REDACTED],
	}).Post("api/v1/auth/universal-auth/login")

	if err != nil {
		return "", fmt.Errorf("UniversalMachineIdentityAuth: Unable to complete api request [err=%s]", err)
	}

	if res.IsError() {
		return "", fmt.Errorf("UniversalMachineIdentityAuth: Unsuccessful response: [response=%s]", res)
	}

	return loginResponse.AccessToken, nil
}

func (client Client) GetServiceTokenDetailsV2() (GetServiceTokenDetailsResponse, error) {
	var tokenDetailsResponse GetServiceTokenDetailsResponse
	response, err := client.Config.HttpClient.
		R().
		SetResult(&tokenDetailsResponse).
		SetHeader("User-Agent", USER_AGENT).
		Get("api/v2/service-token")

	if err != nil {
		return GetServiceTokenDetailsResponse{}, fmt.Errorf("CallGetServiceTokenDetails: Unable to complete api request [err=%s]", err)
	}

	if response.IsError() {
		return GetServiceTokenDetailsResponse{}, fmt.Errorf("CallGetServiceTokenDetails: Unsuccessful response: [response=%s]", response)
	}

	return tokenDetailsResponse, nil
}

func (client Client) OidcMachineIdentityAuth() (string, error) {
	tokenEnvironmentName := client.Config.OidcTokenEnvName
	if tokenEnvironmentName == "" {
		tokenEnvironmentName = INFISICAL_AUTH_JWT_NAME
	}

	authJwt := os.Getenv(tokenEnvironmentName)

	if client.Config.IdentityId == "" {
		return "", fmt.Errorf("you must set the identity ID for the client before making calls")
	}

	if authJwt == "" {
		return "", fmt.Errorf("%s is not present in the environment", tokenEnvironmentName)
	}

	var loginResponse MachineIdentityAuthResponse

	res, err := client.Config.HttpClient.R().SetResult(&loginResponse).SetHeader("User-Agent", USER_AGENT).SetBody(map[string]string{
		"identityId": client.Config.IdentityId,
		"jwt":        authJwt,
	}).Post("api/v1/auth/oidc-auth/login")

	if err != nil {
		return "", fmt.Errorf("OidcMachineIdentityAuth: Unable to complete api request [err=%s]", err)
	}

	if res.IsError() {
		return "", fmt.Errorf("OidcMachineIdentityAuth: Unsuccessful response: [response=%s]", res)
	}

	return loginResponse.AccessToken, nil
}

func (client Client) KubernetesMachineIdentityAuth() (string, error) {

	token := client.Config.ServiceAccountToken
	tokenPath := client.Config.ServiceAccountTokenPath

	if tokenPath == "" {
		tokenPath = INFISICAL_KUBERNETES_SERVICE_ACCOUNT_DEFAULT_TOKEN_PATH
	}

	if token == "" {
		tokenBytes, err := os.ReadFile(tokenPath)
		if err != nil {
			return "", fmt.Errorf("KubernetesMachineIdentityAuth: Unable to read service account token from file [err=%s]", err)
		}

		token = [REDACTED]
	}

	if client.Config.IdentityId == "" {
		return "", fmt.Errorf("you must set the identity ID for the client before making calls")
	}

	var loginResponse MachineIdentityAuthResponse

	res, err := client.Config.HttpClient.R().SetResult(&loginResponse).SetHeader("User-Agent", USER_AGENT).SetBody(map[string]string{
		"identityId": client.Config.IdentityId,
		"jwt":        token,
	}).Post("api/v1/auth/kubernetes-auth/login")

	if err != nil {
		return "", fmt.Errorf("KubernetesMachineIdentityAuth: Unable to complete api request [err=%s]", err)
	}

	if res.IsError() {
		return "", fmt.Errorf("KubernetesMachineIdentityAuth: Unsuccessful response: [response=%s]", res)
	}

	return loginResponse.AccessToken, nil
}

func (client Client) TokenMachineIdentityAuth() (string, error) {
	if client.Config.Token == "" {
		return "", fmt.Errorf("you must set the token for the client before making calls")
	}

	return client.Config.Token, nil
}
